def transform(grid):
    h, w = len(grid), len(grid[0])
    boundary = next((v for row in grid for v in row if v != 0), 0)
    out = [row[:] for row in grid]

    # Fill the interior of downward-pointing triangles whose two diagonal
    # sides are marked in the input.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != boundary:
                continue
            depth = 0
            while r + depth + 1 < h and c - depth - 1 >= 0 and c + depth + 1 < w:
                d = depth + 1
                if grid[r + d][c - d] != boundary or grid[r + d][c + d] != boundary:
                    break
                depth = d
            for d in range(1, depth + 1):
                for x in range(c - d + 1, c + d):
                    if grid[r + d][x] == 0:
                        out[r + d][x] = 2
    return out
