def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next(v for row in grid for v in row if v)
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != color:
                continue
            for dr in (-1, 1):
                d = 1
                while 0 <= r + dr*d < h and c-d >= 0 and c+d < w:
                    rr = r + dr*d
                    if grid[rr][c-d] != color or grid[rr][c+d] != color:
                        break
                    for x in range(c-d+1, c+d):
                        if grid[rr][x] == 0:
                            out[rr][x] = 2
                    d += 1
    return out
